class IntSet {
  private static readonly B = 2069;
  private buckets: number[][] = Array.from({ length: IntSet.B }, () => []);

  add(key: number): void {
    const b = this.buckets[key % IntSet.B];
    if (!b.includes(key)) b.push(key);
  }

  remove(key: number): void {
    const b = this.buckets[key % IntSet.B];
    const i = b.indexOf(key);
    if (i !== -1) {
      b[i] = b[b.length - 1]; // swap with the last key, then drop the end
      b.pop();
    }
  }

  contains(key: number): boolean {
    return this.buckets[key % IntSet.B].includes(key);
  }
}

