class IntSet:
    B = 2069

    def __init__(self):
        self.buckets = [[] for _ in range(self.B)]

    def add(self, key: int) -> None:
        b = self.buckets[key % self.B]
        if key not in b:
            b.append(key)

    def remove(self, key: int) -> None:
        b = self.buckets[key % self.B]
        if key in b:
            i = b.index(key)
            b[i] = b[-1]
            b.pop()

    def contains(self, key: int) -> bool:
        return key in self.buckets[key % self.B]

